    public static void main(String[] args) throws Exception {
        if (args.length >= 1 && args[0].equals("--list")) {
            for (String name : EXAMPLES.keySet()) System.out.println(name);
            return;
        }

        if (args.length >= 2 && args[0].equals("--example")) {
            setLicense();
            Example example = EXAMPLES.get(args[1]);
            if (example == null) {
                System.err.println("Unknown example: " + args[1]);
                System.exit(1);
                return;
            }
            example.run();
            return;
        }

        setLicense();
        printIntro();
        int ok = 0, failed = 0;
        for (Map.Entry<String, Example> entry : EXAMPLES.entrySet()) {
            System.out.println("Running " + entry.getKey() + "...");
            try {
                entry.getValue().run();
                System.out.println("  Completed " + entry.getKey());
                ok++;
            } catch (Throwable t) {
                System.out.println("  Error: " + t.getMessage());
                failed++;
            }
        }
        System.out.println();
        System.out.println("Done. " + ok + " succeeded, " + failed + " failed.");
    }

    private static void printIntro() {
        System.out.println();
        System.out.println("=================================================================");
        System.out.println("  GroupDocs.Total for Java Examples");
        System.out.println("=================================================================");
        System.out.println();
    }

    private static void setLicense() {
        String licensePath = System.getenv("GROUPDOCS_LIC_PATH");
        if (licensePath == null || licensePath.isEmpty()) {
            File[] here = new File(".").listFiles();
            if (here != null) {
                for (File f : here) {
                    if (f.getName().endsWith(".lic")) { licensePath = f.getPath(); break; }
                }
            }
        }
        if (licensePath == null || !new File(licensePath).exists()) {
            return;  // evaluation mode; stay quiet so captured output stays clean
        }
        // Some product License.setLicense() implementations print debug lines to
        // stdout; silence stdout across the licensing loop so none of it can leak
        // into an example's captured output.
        java.io.PrintStream original = System.out;
        System.setOut(new java.io.PrintStream(new java.io.ByteArrayOutputStream()));
        try {
        try { new com.groupdocs.viewer.License().setLicense(licensePath); } catch (Throwable t) { /* product not present or not separately licensed */ }
        try { new com.groupdocs.conversion.licensing.License().setLicense(licensePath); } catch (Throwable t) { /* product not present or not separately licensed */ }
        try { new com.groupdocs.comparison.license.License().setLicense(licensePath); } catch (Throwable t) { /* product not present or not separately licensed */ }
        try { new com.groupdocs.watermark.licenses.License().setLicense(licensePath); } catch (Throwable t) { /* product not present or not separately licensed */ }
        try { new com.groupdocs.metadata.licensing.License().setLicense(licensePath); } catch (Throwable t) { /* product not present or not separately licensed */ }
        try { new com.groupdocs.parser.licensing.License().setLicense(licensePath); } catch (Throwable t) { /* product not present or not separately licensed */ }
        try { new com.groupdocs.merger.licensing.License().setLicense(licensePath); } catch (Throwable t) { /* product not present or not separately licensed */ }
        try { new com.groupdocs.redaction.licensing.License().setLicense(licensePath); } catch (Throwable t) { /* product not present or not separately licensed */ }
        try { new com.groupdocs.signature.licensing.License().setLicense(licensePath); } catch (Throwable t) { /* product not present or not separately licensed */ }
        try { new com.groupdocs.search.licenses.License().setLicense(licensePath); } catch (Throwable t) { /* product not present or not separately licensed */ }
        try { new com.groupdocs.editor.license.License().setLicense(licensePath); } catch (Throwable t) { /* product not present or not separately licensed */ }
        try { new com.groupdocs.annotation.licenses.License().setLicense(licensePath); } catch (Throwable t) { /* product not present or not separately licensed */ }
        } finally {
            System.setOut(original);
        }
    }
